pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value <= address(c).balance || value == 0);
        vm.deal(address(c), value);
        vm.prank(c.owner());
        bool ok = true;
        try c.sendMoney(target, value) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
